const FORMS = [{"id": "blackiron", "tier": 1, "name": "黑铁关羽", "assets": {"attack_cg": {"src": "assets/blackiron-attack_cg.webp", "width": 1672, "height": 941, "label": "黑铁关羽-主动爆发CG-透明候选2"}, "avatar": {"src": "assets/blackiron-avatar.webp", "width": 1254, "height": 1254, "label": "黑铁关羽-头像-透明候选2"}, "card": {"src": "assets/blackiron-card.webp", "width": 1190, "height": 1786, "label": "01-黑铁-UI排版修复1190"}, "biography": {"src": "assets/guanyu-blackiron-biography.webp", "width": 1536, "height": 1024}}, "hero": "guanyu", "story": "乱世尚未把他的名字传出城门时，关羽只是市井中一个衣衫磨旧的卖豆人。清晨的货车突然倾倒，老摊主被困在车轮旁，街上的人一时惊散。他丢下手中的木勺，跨过滚落的豆粒，以肩臂抵住沉重的车架，伸手将老人拉出险处。\n\n没有甲胄，也没有封赏。帆布棚下，邻人重新拾起竹筐，他俯身帮着把散豆拢回袋中。天边似有青龙隐于云间，而真正令众人记住他的，是危急时刻不退的那一步。黑铁之身尚未铸成锋刃，护人的义气却已在市井生根。", "storyTitle": "市井义骨", "move": "义勇破阵\n本轮补全设计，待确认；不代表已实装\n\n选定前方目标后短暂蓄势，向前踏进并挥出一记重击，作用于近身扇形区域；命中造成伤害并短距离击退。自身不瞬移、不变身，不召出完整神龙。蓄势阶段可被硬控制中断；伤害、距离、冷却及击退抗性参数留给战斗原型调校。\n\n身体前倾，双臂发力，衣袖与长髯随动作甩开。特效集中于出力方向，表现未着甲时的刚猛，不以满屏法术取代动作。"}, {"id": "bronze", "tier": 2, "name": "青铜关羽", "assets": {"attack_cg": {"src": "assets/bronze-attack_cg.webp", "width": 1536, "height": 1024, "label": "bronze_cg"}, "avatar": {"src": "assets/bronze-avatar.webp", "width": 1254, "height": 1254, "label": "bronze_avatar"}, "biography": {"src": "assets/bronze-biography.webp", "width": 1536, "height": 1024, "label": "桃园结义-v11-神话源重绘候选"}, "card": {"src": "assets/bronze-card.webp", "width": 1190, "height": 1786, "label": "02-青铜-UI排版修复1190"}}, "hero": "guanyu", "story": "桃花开在乱世的风里。刘备、关羽与张飞将酒盏置于案前，向天地立下同心护民的誓言。关羽知道，今日结下的不是酒席上的热闹，而是往后无论进退、生死，都要彼此担当的诺言。\n\n酒入尘土，三人并肩起身。旧衣之外添上了朴实的青铜甲，刀柄第一次在掌中显得如此沉重：他要守住的，从此不只是身前的一人。风掠过桃枝，青龙之息仿佛随誓言醒来，却没有盖过三人相握的手。青铜关羽由市井义士踏上征途，力量的起点，是亲口答应的那一声不负。", "storyTitle": "桃园结义", "move": "青龙初斩\n本轮补全设计，待确认；不代表已实装\n\n锁定前方方向，短暂蓄势后斜劈，攻击狭长扇形范围内敌人；中心刀路承受更强冲击，边缘只受基础伤害。命中后不追加无来源的多段爆炸。蓄势阶段受硬控制可中断，具体数值待原型调校。\n\n低位沉身拧腰，双手分握长柄向下斜劈；肩后仅初醒青龙首和一条收束刀光，保持青铜阶段朴素的甲衣。"}, {"id": "silver", "tier": 3, "name": "白银关羽", "assets": {"attack_cg": {"src": "assets/silver-attack_cg.webp", "width": 1536, "height": 1024, "label": "silver_cg"}, "avatar": {"src": "assets/silver-avatar.webp", "width": 1254, "height": 1254, "label": "silver_avatar"}, "biography": {"src": "assets/silver-biography.webp", "width": 1536, "height": 1024, "label": "温酒请战-v17-原图冻结-武器局部合成"}, "card": {"src": "assets/silver-card.webp", "width": 1190, "height": 1786, "label": "03-白银-UI排版修复1190"}}, "hero": "guanyu", "story": "帐中诸将沉默，帐外关前的凶威仍未散去。案上的酒刚刚温热，关羽已从席间起身，请命出战。他没有急着饮下那杯酒，只将长刀握稳，留下一句待归再饮。\n\n风掀开帐帘，银色甲片在天光中一亮。众人的目光从怀疑转为凝视，关羽却只看向阵前。那一刻，他尚未挥刀，也未见胜负，所有勇气都收在平静的神情里。白银之锐不是喧哗的夸耀，而是明知强敌在前，仍愿替众人先行一步。此后，人们以那杯未冷的酒，记住一名斩将者走出营帐的背影。", "storyTitle": "温酒请战", "move": "阵前斩将\n本轮补全设计，待确认；不代表已实装\n\n指定一名敌方单位，完成短距突进后重斩；主要伤害集中于指定目标，相邻敌人只受刀势余波。不穿越不可通行地形，目标在出刀前失效则不追踪地图外位置。突进距离、伤害分配与冷却待原型调校。\n\n长柄与刀刃保持刚性连贯，出刀重心明确；青龙力量集中沿刀路推进，不把白银阶段直接画成神相。"}, {"id": "gold", "tier": 4, "name": "黄金关羽", "assets": {"attack_cg": {"src": "assets/gold-attack_cg.webp", "width": 1536, "height": 1024, "label": "gold_cg"}, "avatar": {"src": "assets/gold-avatar.webp", "width": 1254, "height": 1254, "label": "gold_avatar"}, "biography": {"src": "assets/gold-biography.webp", "width": 1536, "height": 1024, "label": "千里护行-神话源重绘-直杆修复"}, "card": {"src": "assets/gold-card.webp", "width": 1190, "height": 1786, "label": "04-黄金-UI排版修复1190"}}, "hero": "guanyu", "story": "富贵与重赏留在身后，关羽护着车马踏上寻兄的长路。关隘一道接着一道，前路时而被山雨遮住，时而被横刀的军阵截断。他没有让车中的人独自面对危险，每到险处，总先将自己的身影挡在道路中央。\n\n赤兔踏过泥水，金甲映着残阳。那柄长刀指向的并非新的功名，而是一条让同行者平安通过的路。关羽知道，走完千里容易，守住千里间的每一次承诺才难。于是他一次次回身确认车马仍在，再向下一道关口行去。黄金关羽的威势已足以震慑群敌，但使他不曾偏离方向的，仍是桃园中立下的那份义。", "storyTitle": "千里护行", "move": "千里破关\n本轮补全设计，待确认；不代表已实装\n\n沿指定方向发起连续破阵突击，首段长刀开路，随后以青龙刀势横扫前方；每个目标每段只结算一次。移动路径受地形阻挡，不能穿墙追击。段数、伤害、冲刺距离及控制强度待原型调校。\n\n关羽与长刀形成向前贯穿的进攻轮廓，青龙护住进路两侧；保留黄金甲、绿袍与长髯，不另换神魔形态。"}, {"id": "mecha5", "tier": 5, "name": "机甲关羽", "assets": {"avatar": {"src": "assets/mecha5-avatar.webp", "width": 1254, "height": 1254, "label": "五星机甲关羽-头像-透明"}, "card": {"src": "assets/mecha5-card.webp", "width": 1190, "height": 1786, "label": "guanyu-piloted-dragon-mecha-5star"}, "biography": {"src": "assets/mecha5-biography.webp", "width": 1536, "height": 1024, "label": "五星机甲关羽-传记-青龙启甲-古代工坊组装重绘"}, "attack_cg": {"src": "assets/mecha5-attack_cg.webp", "width": 1536, "height": 1024, "label": "五星机甲关羽-放招-腾跃斜劈-透明"}}, "story": "山城被围，工坊中的炉火彻夜未熄。百工以青铜为骨、精铁为筋，把绞盘与齿轮连成巨甲的关节。关羽沿木架走入尚未封合的胸舱，等待这副庞大的身躯与自己接通。\n\n铁链缓缓绷紧，龙首肩甲、双臂与胸甲从不同吊架降下。匠人扶正传动轴，逐一落销，腿甲敞开的骨架里响起铜齿咬合的声音。前景的青龙巨刃仍架在夹具上校准握距，侧旁的机械赤兔也尚在安装四肢与外甲。人、甲、刀、马，就在满城匠人的协力中渐渐成形。\n\n最后一枚锁销落下之前，关羽回望炉火旁忙碌的众人。待巨甲迈出工坊，他要将这些亲手铸出它的人，护在刀锋之后。", "move": "巨甲腾跃而起，屈膝拧身，双手分握长柄斜劈而下。青色刀光沿巨刃划出连贯弧线，胸舱中的驾驶者清楚可见。动作表现重装机体蓄势后猛然反击的力量。", "storyTitle": "青龙启甲", "hero": "guanyu"}, {"id": "heritage5", "tier": 5, "name": "传承关羽", "assets": {"avatar": {"src": "assets/heritage5-avatar.webp", "width": 1254, "height": 1254, "label": "传承关羽-头像-透明"}, "biography": {"src": "assets/heritage5-biography.webp", "width": 1536, "height": 1024, "label": "传承关羽-传记-一刀分沧海"}, "attack_cg": {"src": "assets/heritage5-attack_cg.webp", "width": 1536, "height": 1024, "label": "传承关羽-放招-水淹七军-腾空回斩-透明"}, "card": {"src": "assets/heritage5-card.webp", "width": 1190, "height": 1786}}, "story": "暴雨压城，洪流漫过山川，战船在浪峰间起伏。关羽踏入怒涛，双手沉握青龙偃月刀，将奔腾的传承之力压入刀锋。\n\n一刀落下，洪水从脚前裂向天际。巨浪向两侧拔起如城壁，水底的岩脊、淤沙与残木尽数显露。刀光尚未散去，水墙之巅的战船已小如芥子。关羽压刀收势，长髯迎风，独立于乍现的海底长廊；远处的城门，正落在这一刀所指的尽头。\n\n此篇借“水淹七军”的意象展开幻想。一刀分海、露出海底与传承神力均为游戏虚构。", "move": "关羽腾空拧身，双手分握长柄回旋横斩，一腿屈起、一腿伸展。刀锋带出连续的青碧水刃，金角青龙沿水势盘绕向前。身体、长刀与水龙共同形成旋转的进攻走势。", "storyTitle": "一刀分沧海", "newCard": true, "hero": "guanyu"}, {"id": "divine5", "tier": 5, "name": "神关羽", "assets": {"avatar": {"src": "assets/divine5-avatar.webp", "width": 1254, "height": 1254, "label": "神关羽-头像-透明"}, "biography": {"src": "assets/divine5-biography.webp", "width": 1536, "height": 1024, "label": "神关羽-传记-千秋共仰"}, "attack_cg": {"src": "assets/divine5-attack_cg.webp", "width": 1536, "height": 1024, "label": "神关羽-放招-义薄云天-透明"}, "card": {"src": "assets/divine5-card.webp", "width": 1190, "height": 1786}}, "story": "殿宇几度新修，阶前的香火仍在升起。画卷将后世不同年代的庙宇叠入同一片云光：帝王与官员执礼而来，行旅、军民与老幼也停在阶前，向武圣致敬。人们记住他的勇武，也将危难之中守诺护人的愿望寄托在这尊神相身上。\n\n香烟穿过重重庙院，青袍金甲的关羽端坐殿中，赤面长髯仍保留着人们熟悉的模样。光从神相身后铺开，照见一代又一代走过庙门的人。无数次郑重的叩拜，构成了“神关羽”的由来。\n\n祭祀画面采用跨时代艺术蒙太奇，并非记载所有帝王都曾亲祭关羽，也不表示不同朝代的人真实同场。", "move": "关羽凌空屈膝旋身，双手高举于额顶结印，衣袍与红绸随转势扬开。金翠冠冕与头后圣轮聚起光辉，三面宽阔的青金护盾沿身前展开，连成护域，表现“义薄云天”的神圣护佑之势。", "storyTitle": "千秋共仰", "newCard": true, "hero": "guanyu"}, {"id": "demon5", "tier": 5, "name": "魔关羽", "assets": {"avatar": {"src": "assets/demon5-avatar.webp", "width": 1254, "height": 1254, "label": "魔关羽-头像-透明"}, "card": {"src": "assets/demon5-card.webp", "width": 1190, "height": 1786, "label": "guanyu-infernal-06-5star"}, "biography": {"src": "assets/demon5-biography.webp", "width": 1536, "height": 1024, "label": "魔关羽-传记-麦城未醒"}, "attack_cg": {"src": "assets/demon5-attack_cg.webp", "width": 1536, "height": 1024, "label": "魔关羽-放招-透明"}}, "story": "残旗垂在冷雨里。关羽被敌兵按跪在泥水中，身后的行刑刀已然举起。他没有低头，只透过散乱的长髯望向天空。烟灰之上，一场不肯熄灭的复仇在他心中展开。\n\n在那片想象里，他须发尽白，赤面生焰，黑龙载着巨大的魔身破云而起。青龙偃月刀化作夸张的巨刃，随着横扫卷起江潮，将记忆中白衣渡江的军阵连人带舟掀向半空。他想把失守、背叛与无法挽回的败局，一刀劈回发生之前。\n\n可烟云之下，关羽仍被按着双肩，那柄行刑刀也尚未落下。黑龙、魔身与翻卷的白衣，都是这一瞬间的心中幻象。画面以麦城与白衣渡江为背景作幻想改编，现实并未被复仇的想象改写。", "move": "魔关羽握住残旗，前伸魔掌牵引赤红魂焰，黑龙随掌势向前扑出。白发、赤瞳与怒涛般的焰流延续最终魔卡的复仇形象；本篇传记的改写不另设新的主动技能名称。", "storyTitle": "麦城未醒", "hero": "guanyu"}, {"id": "mecha6", "tier": 6, "name": "封侯机甲关羽", "assets": {"avatar": {"src": "assets/mecha6-avatar.webp", "width": 1254, "height": 1254, "label": "六星机甲关羽-头像-透明"}, "card": {"src": "assets/guanyu-mecha6-card.webp", "width": 1024, "height": 1536}, "biography": {"src": "assets/mecha6-biography.webp", "width": 1536, "height": 1024, "label": "六星机甲关羽-传记-擎天护城"}, "attack_cg": {"src": "assets/mecha6-attack_cg.webp", "width": 1536, "height": 1024, "label": "六星机甲关羽-放招-擎天巨盾-透明"}}, "story": "黑云压过群山，城中的人们抬头望去，只见苍穹越来越暗。关羽在胸舱中稳住操纵柄，驱动青金巨甲立于城上，双臂向天举起。\n\n环形护阵与龙首翼片一同展开，青色光幕从掌心铺向四方，连成覆盖城郭的穹顶。沉重的黑暗留在天幕之外，暖光落回城墙、屋瓦与人群之间。孩子松开了紧攥的衣角，街上的人也终于停下奔逃，仰望撑住天幕的身影。\n\n巨甲没有退让。关羽守着这座城，也守着每一个还要平安归家的人。楼阁间亮起的灯火，便是他继续举起双臂的理由。", "move": "巨甲屈膝沉身，将近身高的宽厚青金巨盾向前撑出，另一手长刀斜护侧翼。完整盾面、龙纹与收束的能量线构成画面重心，背轮、龙翼及胸舱驾驶者保持可辨。只表现守御蓄势，不加入敌方光束或弹道。", "storyTitle": "擎天护城", "hero": "guanyu"}, {"id": "heritage6", "tier": 6, "name": "传承关羽 · 龙魂真身", "assets": {"card": {"src": "assets/guanyu-heritage6-card.webp", "width": 1024, "height": 1536}, "avatar": {"src": "assets/guanyu-heritage6-avatar.webp", "width": 1254, "height": 1254, "status": "candidate_pending_review"}, "attack_cg": {"src": "assets/guanyu-heritage6-attack_cg.webp", "width": 1024, "height": 1536, "status": "candidate_pending_review"}, "biography": {"src": "assets/guanyu-heritage6-biography.webp", "width": 1536, "height": 1024, "status": "candidate_pending_review"}}, "hero": "guanyu", "storyTitle": "以身为堤", "story": "汉水暴涨的那一夜，城门前挤满了无处可去的人。断桥被卷走，旧堤在黑浪里一段段崩塌。关羽原本已经挥刀分开洪流，却听见身后仍有人呼喊失散的亲人。他没有追击，也没有收刀入城，而是把封侯印举向天穹，立誓：只要还有一人未渡，便不让江水合拢。\n印上的龙纹应声亮起。天光穿透雨幕，沉睡于江底的龙魂沿着刀锋升起，与他的身躯相合。青鳞替代了双腿，巨大的龙尾盘过断堤；力量不再只是附着于铠甲，而成为他的血肉。关羽以龙身环住村落，承受一波又一波浊浪，为百姓留下一条通向城门的干路。\n老人背上的孩子回头望去，只看见青龙般的身影俯在洪水与人间之间。世人称他龙魂真身，并非因为他能唤来多大的浪，而是因为滔天的浪，终于在他身前止步。", "move": "盘龙逆潮\n动作演出：龙尾盘卷蓄势，身体腾空反拧，双手握住青龙偃月刀由低处反撩上挑，随后水带沿刀势扫向前方；动作与卡面持刀站姿完全区分。\n玩法草案：对前方扇形区域造成一次斩击；随后沿刀势形成一道推进的水浪，对命中敌人施加短暂减速。龙尾回卷时，在自身附近留下短时护域，为友方提供护盾。斩击、水浪、护域分别判定，同一水浪对同一目标不重复命中。\n数值状态：伤害、范围、持续时间、冷却与护盾量待战斗测试确定，不作为已定稿规则。\n卡面现有被动名称沿用：龙骧 +1、震夏 +1、武圣 +1。本次不改卡面被动定义。"}, {"id": "divine6", "tier": 6, "name": "神关羽 · 六臂帝君", "assets": {"card": {"src": "assets/guanyu-divine6-card.webp", "width": 1024, "height": 1536}, "avatar": {"src": "assets/guanyu-divine6-avatar.webp", "width": 1254, "height": 1254}, "attack_cg": {"src": "assets/guanyu-divine6-attack_cg.webp", "width": 1024, "height": 1536}, "biography": {"src": "assets/guanyu-divine6-biography.webp", "width": 1536, "height": 1024}}, "hero": "guanyu", "story": "神关羽·六星封侯·六臂帝君\n新增配套候选，待用户确认。以下为游戏架空剧情，不作历史事实叙述。\n\n传记：万灯成誓\n风雨封住了山路，逃难的人挤进一座破旧关庙。神像金漆剥落，供桌也早已空了。老人把最后一截蜡烛点起，年轻人让出干燥的衣裳，抱着孩子的母亲低声求的不是富贵，只是所有人都能平安走过今夜。\n一盏灯递给下一双手，庙外的黑暗里，渐渐亮起了一条路。关羽听见的并非帝王的敕封，而是凡人彼此守望的誓言。旧庙门楣上，封侯印映出一道天光；金玉神躯从云中显现，六臂各承一愿：持刀断厄，执印守约，合掌安魂，开手护生。龙云承起破碎山道，光从他的掌心落向每一个举灯的人。\n此后，人们称其为六臂帝君。他没有停留在最高的天门，只把最前的一只手，伸向了最难走的那段人间。\n\n局内出招：六仪镇厄\n画面：金龙云躯盘旋前倾，主臂驱动青龙偃月刀斜向重斩，其余法臂结印张开，刀势与护生金环在同一瞬间成形。明确区别于卡面正立展示姿态。\n机制建议（待平衡确认）：对正前方扇形区域造成一次主斩伤害，同时为范围内友军施加短时护盾；命中带有印记的敌人时触发一次镇厄效果。此处不擅自锁定伤害倍率、时长、冷却或控制数值，沿用项目战斗系统统一调参。\n\n头像说明：独立绘制的冠冕近景头像，保留红面长髯、翡翠金冠、白金龙甲与大面积神性背光；不使用卡面裁切替代。\n", "storyTitle": "万灯成誓", "move": "神关羽·六星封侯·六臂帝君\n新增配套候选，待用户确认。以下为游戏架空剧情，不作历史事实叙述。\n\n传记：万灯成誓\n风雨封住了山路，逃难的人挤进一座破旧关庙。神像金漆剥落，供桌也早已空了。老人把最后一截蜡烛点起，年轻人让出干燥的衣裳，抱着孩子的母亲低声求的不是富贵，只是所有人都能平安走过今夜。\n一盏灯递给下一双手，庙外的黑暗里，渐渐亮起了一条路。关羽听见的并非帝王的敕封，而是凡人彼此守望的誓言。旧庙门楣上，封侯印映出一道天光；金玉神躯从云中显现，六臂各承一愿：持刀断厄，执印守约，合掌安魂，开手护生。龙云承起破碎山道，光从他的掌心落向每一个举灯的人。\n此后，人们称其为六臂帝君。他没有停留在最高的天门，只把最前的一只手，伸向了最难走的那段人间。\n\n局内出招：六仪镇厄\n画面：金龙云躯盘旋前倾，主臂驱动青龙偃月刀斜向重斩，其余法臂结印张开，刀势与护生金环在同一瞬间成形。明确区别于卡面正立展示姿态。\n机制建议（待平衡确认）：对正前方扇形区域造成一次主斩伤害，同时为范围内友军施加短时护盾；命中带有印记的敌人时触发一次镇厄效果。此处不擅自锁定伤害倍率、时长、冷却或控制数值，沿用项目战斗系统统一调参。\n\n头像说明：独立绘制的冠冕近景头像，保留红面长髯、翡翠金冠、白金龙甲与大面积神性背光；不使用卡面裁切替代。\n"}, {"id": "demon6", "tier": 6, "name": "魔关羽 · 冥龙魔君", "assets": {"card": {"src": "assets/guanyu-demon6-card.webp", "width": 1024, "height": 1536}, "avatar": {"src": "assets/guanyu-demon6-avatar.webp", "width": 1254, "height": 1254, "status": "candidate_pending_review"}, "attack_cg": {"src": "assets/guanyu-demon6-attack_cg.webp", "width": 1024, "height": 1536, "status": "candidate_pending_review"}, "biography": {"src": "assets/guanyu-demon6-biography.webp", "width": 1536, "height": 1024, "status": "candidate_pending_review"}}, "hero": "guanyu", "storyTitle": "断锁归冥", "story": "（架空幻想支线，非历史事件记述；本次补全稿，待确认。）\n\n麦城的冷雨早已停了，梦里的铁索却始终没有松开。每当关羽闭上眼，白衣渡江的船影便从黑水中浮起，失散的军旗也一次次沉回深处。他曾以为，只要向复仇的幻象伸出手，就能把这一切重新夺回。\n\n冥渊于是回应了他。无数锁链将他拖向一座沉没的城门，黑龙的鳞甲沿着伤痕生长，双翼从背后展开，持刀的手化作巨爪。那力量要他抛下姓名，只做一头听凭怨恨驱使的恶龙。关羽却在黑水里看见了旧部残存的魂影，也看见那面仍未完全沉没的绿旗。\n\n他没有向幻象中的敌军挥刀，而是先斩断了锁住军旗的铁链。刀锋贯穿冥门，赤红脉冲沿断链奔涌，束缚诸魂的锁环接连崩裂。绿旗重新升起时，白发的魔君立在裂开的门槛上，巨爪握紧断锁，翼影替身后的魂火挡住深渊。\n\n从此，龙身不再是囚笼。那一夜并未改写败局，也没有令往事复生；它只是让关羽在无尽的复仇之梦里，重新握住了自己挥刀的理由。", "move": "冥龙断狱\n演出：双翼收拢蓄势，龙足离地，身躯斜向俯冲。巨爪先行撕开前方空间，偃月刃从身侧反向扫出，形成一道完整的赤红脉冲刀弧。收招时双翼展开制动，绿旗沿回旋方向掠过。\n玩法提案：向选定方向突进，对沿途敌人造成一次斩击；终点释放较宽的脉冲冲击，短暂击退近处敌人。两段动作构成一次技能，不叠加重复命中同一区段的伤害判定。伤害倍率、距离、冷却与控制时长待统一数值测试，不将提案当作已定规则。"}, {"hero": "zhangfei", "id": "blackiron", "tier": 1, "name": "黑铁张飞", "assets": {"card": {"src": "assets/zhangfei-blackiron-card.webp", "width": 1190, "height": 1786}, "attack_cg": {"src": "assets/zhangfei-blackiron-attack_cg.webp", "width": 1536, "height": 1024}, "avatar": {"src": "assets/zhangfei-blackiron-avatar.webp", "width": 1254, "height": 1254}, "biography": {"src": "assets/zhangfei-blackiron-biography.webp", "width": 1536, "height": 1024, "status": "candidate_pending_review"}}, "story": "涿郡的市井尚未听见战鼓，流民已经走到了张飞的门前。他放下屠刀，打开粮仓，把原本留作买卖的粮食分给饥民。门边的长矛与行囊，是他为自己留下的另一条路：世道既不能让人安生，便提矛护住眼前的人。\n\n游戏化叙事与招式设计提案，非历史考证；技能名称及机制待确认，未设定数值。", "storyTitle": "解囊起义", "move": "奋身破阵：张飞沉肩蓄力，借踏步把蛇矛向前送出。招式强调肉身力量与初出茅庐的锐气，不加入神魔或机甲特效。\n\n技能名称及机制待确认，未设定数值。"}, {"hero": "zhangfei", "id": "bronze", "tier": 2, "name": "青铜张飞", "assets": {"card": {"src": "assets/zhangfei-bronze-card.webp", "width": 1190, "height": 1786}, "biography": {"src": "assets/zhangfei-bronze-biography.webp", "width": 1536, "height": 1024}, "attack_cg": {"src": "assets/zhangfei-bronze-attack_cg.webp", "width": 1536, "height": 1024}, "avatar": {"src": "assets/zhangfei-bronze-avatar.webp", "width": 1254, "height": 1254}}, "storyTitle": "散财聚义", "story": "张飞把家中的钱粮、布匹与兵器一件件摆上长桌，招呼乡人前来领用。刘备记下愿意同行的名字，关羽把粮袋递给即将出发的队伍。聚在一起的原本是种田、赶车、做买卖的人，此刻却有了同一个去处：让身后的人能够平安生活。\n\n游戏化叙事与招式设计提案，非历史考证；技能名称及机制待确认，未设定数值。", "move": "虎胆横扫：双手持矛，以腰胯转动带出横向扫击。表现整齐、明确的一道劲风，突出青铜武将的团队开路能力。\n\n技能名称及机制待确认，未设定数值。"}, {"hero": "zhangfei", "id": "silver", "tier": 3, "name": "白银张飞", "assets": {"card": {"src": "assets/zhangfei-silver-card.webp", "width": 1190, "height": 1786}, "biography": {"src": "assets/zhangfei-silver-biography.webp", "width": 1536, "height": 1024}, "attack_cg": {"src": "assets/zhangfei-silver-attack_cg.webp", "width": 1536, "height": 1024}, "avatar": {"src": "assets/zhangfei-silver-avatar.webp", "width": 1254, "height": 1254}}, "storyTitle": "虎牢争锋", "story": "虎牢关下，鼓声一层压着一层。张飞看见兄长的战线被逼退，便提矛迎上最锋利的那一点。他的吼声不是逞勇的炫耀，而是给身后同伴的信号：这里由我顶住，你们尽管向前。此篇沿用三英战吕布的文学演义意象。\n\n游戏化叙事与招式设计提案，非历史考证；技能名称及机制待确认，未设定数值。", "move": "虎牢突刺：一步压低重心，随后旋身送出贯穿式直刺。矛尖凝出虎形劲气，但不改变人体形态。\n\n技能名称及机制待确认，未设定数值。"}, {"hero": "zhangfei", "id": "gold", "tier": 4, "name": "黄金张飞", "assets": {"card": {"src": "assets/zhangfei-gold-card.webp", "width": 1190, "height": 1786}, "biography": {"src": "assets/zhangfei-gold-biography.webp", "width": 1536, "height": 1024}, "attack_cg": {"src": "assets/zhangfei-gold-attack_cg.webp", "width": 1536, "height": 1024}, "avatar": {"src": "assets/zhangfei-gold-avatar.webp", "width": 1254, "height": 1254}}, "storyTitle": "桥后生路", "story": "桥面上，张飞横矛独立；桥面下，水声吞没了急促的脚步。百姓的车辆还没有走远，他便把所有追兵的目光引到自己身上。那一刻，巨大的虎影从怒喝中升起，挡住了桥头，也替身后的人换来一段继续逃生的路。\n\n游戏化叙事与招式设计提案，非历史考证；技能名称及机制待确认，未设定数值。", "move": "长坂惊魂：稳住脚步后扭身横矛，怒喝化成宽阔的虎形震波，向正前方推进。大片声浪与清晰轮廓优先，不使用碎闪点。\n\n技能名称及机制待确认，未设定数值。"}, {"hero": "zhangfei", "id": "heritage5", "tier": 5, "name": "传承张飞", "assets": {"card": {"src": "assets/zhangfei-heritage5-card.webp", "width": 1024, "height": 1536, "status": "candidate_pending_review"}, "avatar": {"src": "assets/zhangfei-heritage5-avatar.webp", "width": 1254, "height": 1254, "status": "candidate_pending_review"}, "attack_cg": {"src": "assets/zhangfei-heritage5-attack_cg.webp", "width": 1254, "height": 1254, "status": "candidate_pending_review", "qa_note": "Transparent alpha and attack pose verified."}, "biography": {"src": "assets/zhangfei-heritage5-biography.webp", "width": 1536, "height": 1024, "status": "candidate_pending_review", "qa_note": ""}}, "story": "桥后的车辙里还有孩子的哭声，追兵的旗影却已漫过坡顶。张飞让最后一辆车先走，独自横矛桥头。众人只记得那一声怒喝，却很少有人看见他始终没有回头：他怕自己一回头，身后的人便以为他也在害怕。此篇为基于长坂传说的游戏化演绎。", "move": "断桥惊雷：低身跨步，以蛇矛横扫前方；一条凝实虎形声浪沿地面推开敌阵。\n\n技能名称及机制待确认，未设定数值。", "storyTitle": "一声护归途"}, {"hero": "zhangfei", "id": "divine5", "tier": 5, "name": "神张飞", "assets": {"card": {"src": "assets/zhangfei-divine5-card.webp", "width": 1024, "height": 1536, "status": "candidate_pending_review"}, "avatar": {"src": "assets/zhangfei-divine5-avatar.webp", "width": 1254, "height": 1254, "status": "candidate_pending_review"}, "attack_cg": {"src": "assets/zhangfei-divine5-attack_cg.webp", "width": 1254, "height": 1254, "status": "candidate_pending_review", "qa_note": "True alpha verified; dynamic attack pose; divine5 two arms, divine6 four arms."}, "biography": {"src": "assets/zhangfei-divine5-biography.webp", "width": 1536, "height": 1024, "status": "candidate_pending_review", "qa_note": ""}}, "story": "山洪过后，百姓把无家可归的人迎进张飞祠。长明灯下，一尊怒目的神像忽然俯下身，将倒塌的门梁托起。供奉他的不是金玉，而是人们愿意为陌生人留出的一席安稳；于是守门的将军，成了护城的神。此为游戏原创神话。", "move": "金阙镇岳：侧身踏空，双掌错开长矛，以环形金色山岳法印镇住前方。\n\n技能名称及机制待确认，未设定数值。", "storyTitle": "庙门不闭"}, {"hero": "zhangfei", "id": "demon5", "tier": 5, "name": "魔张飞", "assets": {"card": {"src": "assets/zhangfei-demon5-card.webp", "width": 1024, "height": 1536, "status": "candidate_pending_review"}, "avatar": {"src": "assets/zhangfei-demon5-avatar.webp", "width": 1254, "height": 1254, "status": "candidate_pending_review"}}, "story": "梦里没有庆功的酒，只有骤然熄灭的灯与未能说完的嘱托。张飞在黑暗里握紧蛇矛，把背叛留下的恐惧一寸寸折成锁链。他不肯让怒火吞掉自己的姓名，于是先锁住心中的猛虎，再向漫长的夜走去。此为虚构魔化支线，不作真实死因重演。\n\n游戏化叙事与招式设计提案，非历史考证；机制数值待确认。", "move": "断链噬夜：半空扭身反刺，左臂甩开断链，黑虎轮廓沿蛇矛突进，红色脉冲以宽环扩散。\n\n技能名称及机制待确认，未设定数值。", "storyTitle": "帐中未尽的怒火"}, {"hero": "zhangfei", "id": "mecha5", "tier": 5, "name": "机甲张飞", "assets": {"card": {"src": "assets/zhangfei-mecha5-card.webp", "width": 1024, "height": 1536, "status": "candidate_pending_review"}, "avatar": {"src": "assets/zhangfei-mecha5-avatar.webp", "width": 1254, "height": 1254, "status": "candidate_pending_review"}}, "story": "旧城门被撞裂的那一夜，工匠没有再赶造一扇更厚的门。他们把青铜虎首、承重机关与未冷却的甲片送到张飞面前。张飞站在吊架中央，让一副能替百姓挡住冲撞的钢铁骨架合拢。最后装上的不是铠甲，而是那柄仍由他亲手掌握的蛇矛。此为幻想机甲支线。\n\n游戏化叙事与招式设计提案，非历史考证；机制数值待确认。", "move": "虎贲崩山：屈膝跃进，整副重甲旋转，以机械蛇矛斜向下贯砸，推力结构清楚可见。\n\n技能名称及机制待确认，未设定数值。", "storyTitle": "百锻为骨"}, {"hero": "zhangfei", "id": "heritage6", "tier": 6, "name": "传承张飞", "assets": {"card": {"src": "assets/zhangfei-heritage6-card.webp", "width": 1024, "height": 1536, "status": "candidate_pending_review"}, "avatar": {"src": "assets/zhangfei-heritage6-avatar.webp", "width": 1254, "height": 1254, "status": "candidate_pending_review"}, "attack_cg": {"src": "assets/zhangfei-heritage6-attack_cg.webp", "width": 1254, "height": 1254, "status": "revision_pending", "qa_note": "Transparent alpha verified; heritage6 anatomy requires final reviewer attention to rear paw silhouette."}, "biography": {"src": "assets/zhangfei-heritage6-biography.webp", "width": 1536, "height": 1024, "status": "candidate_pending_review", "qa_note": ""}}, "story": "人间的嗓音总会嘶哑，守关的誓言却未曾停息。山川记住长坂桥头的怒喝，将沉睡的虎魄交给张飞。他不再只是持矛的武将：筋骨化作雷霆，双足踏住险关，成为百姓退路上不会后退的山。此为幻想进阶故事。", "move": "虎魄裂霆：虎爪蹬空，双臂逆拧蛇矛后向下贯击；成块的蓝白雷弧随虎形脊背掠出。\n\n技能名称及机制待确认，未设定数值。", "storyTitle": "群山借我一声"}, {"hero": "zhangfei", "id": "divine6", "tier": 6, "name": "神张飞", "assets": {"card": {"src": "assets/zhangfei-divine6-card.webp", "width": 1024, "height": 1536, "status": "candidate_pending_review"}, "avatar": {"src": "assets/zhangfei-divine6-avatar.webp", "width": 1254, "height": 1254, "status": "candidate_pending_review"}, "attack_cg": {"src": "assets/zhangfei-divine6-attack_cg.webp", "width": 1254, "height": 1254, "status": "candidate_pending_review", "qa_note": "True alpha verified; dynamic attack pose; divine5 two arms, divine6 four arms."}, "biography": {"src": "assets/zhangfei-divine6-biography.webp", "width": 1536, "height": 1024, "status": "candidate_pending_review", "qa_note": ""}}, "story": "雷云压低到城墙时，祭坛上的灯一盏盏灭去。张飞却听见黑暗里仍有人安慰孩子。他化出四臂，把倾覆的苍穹向两侧推开；一双手执矛拒灾，一双手托住人间。神威不是让人跪下，而是让他们能够重新站起。此为幻想进阶故事。", "move": "四极擎天：四臂交错展开，双手横矛、双手压下完整巨型玉印光盘，形成清晰四向冲击。\n\n技能名称及机制待确认，未设定数值。", "storyTitle": "替人间撑天"}, {"hero": "zhangfei", "id": "demon6", "tier": 6, "name": "魔张飞", "assets": {"card": {"src": "assets/zhangfei-demon6-card.webp", "width": 1024, "height": 1536, "status": "candidate_pending_review"}, "avatar": {"src": "assets/zhangfei-demon6-avatar.webp", "width": 1254, "height": 1254, "status": "candidate_pending_review"}}, "story": "那只猛虎终于挣断了梦中的锁链，却没有扑向无辜的人。张飞将自己的意识埋进它的脊骨，让每一寸利爪都记得该守住什么。冥夜因他裂开一道缝；从缝里走出的不再是旧日武将，却依然是那个肯为同伴挡在前面的人。此为幻想进阶故事。\n\n游戏化叙事与招式设计提案，非历史考证；机制数值待确认。", "move": "冥虎裂界：虎躯低伏后纵跃，双爪与蛇矛一同划出三道宽阔裂隙，拒绝细碎光点。\n\n技能名称及机制待确认，未设定数值。", "storyTitle": "怒火的缰绳"}, {"hero": "zhangfei", "id": "mecha6", "tier": 6, "name": "机甲张飞", "assets": {"card": {"src": "assets/zhangfei-mecha6-card.webp", "width": 1024, "height": 1536, "status": "candidate_pending_review"}, "avatar": {"src": "assets/zhangfei-mecha6-avatar.webp", "width": 1254, "height": 1254, "status": "candidate_pending_review"}}, "story": "机关甲本该在最后一次冲撞后停下，张飞却把蛇矛插进城基，让尚未熄灭的炉心与整座城的守备机关相连。四足支起新的门洞，四臂托住倾斜的城墙。撤离的人从他身下经过时，听见的不是齿轮，而是一句熟悉的吼声：往前走。此为幻想进阶故事。\n\n游戏化叙事与招式设计提案，非历史考证；机制数值待确认。", "move": "玄虎踏关：四足机躯腾跃，两臂以矛前刺，另外两臂展开完整大型护甲盾；不画敌方光束。\n\n技能名称及机制待确认，未设定数值。", "storyTitle": "此身即城门"}, {"hero": "liubei", "id": "blackiron", "tier": 1, "name": "黑铁刘备", "assets": {"card": {"src": "assets/liubei-blackiron-card.webp", "width": 1190, "height": 1786}, "attack_cg": {"src": "assets/liubei-blackiron-attack_cg.webp", "width": 1536, "height": 1024}, "avatar": {"src": "assets/liubei-blackiron-avatar.webp", "width": 1254, "height": 1254}, "biography": {"src": "assets/liubei-blackiron-biography.webp", "width": 1536, "height": 1024, "status": "candidate_pending_review"}}, "storyTitle": "一履之诺"}, {"hero": "liubei", "id": "bronze", "tier": 2, "name": "青铜刘备", "assets": {"card": {"src": "assets/liubei-bronze-card.webp", "width": 1190, "height": 1786}, "biography": {"src": "assets/liubei-bronze-biography.webp", "width": 1536, "height": 1024}, "attack_cg": {"src": "assets/liubei-bronze-attack_cg.webp", "width": 1536, "height": 1024}, "avatar": {"src": "assets/liubei-bronze-avatar.webp", "width": 1254, "height": 1254}}}, {"hero": "liubei", "id": "silver", "tier": 3, "name": "白银刘备", "assets": {"card": {"src": "assets/liubei-silver-card.webp", "width": 1190, "height": 1786}, "biography": {"src": "assets/liubei-silver-biography.webp", "width": 1536, "height": 1024}, "attack_cg": {"src": "assets/liubei-silver-attack_cg.webp", "width": 1536, "height": 1024}, "avatar": {"src": "assets/liubei-silver-avatar.webp", "width": 1254, "height": 1254}}}, {"hero": "liubei", "id": "gold", "tier": 4, "name": "黄金刘备", "assets": {"card": {"src": "assets/liubei-gold-card.webp", "width": 1190, "height": 1786}, "biography": {"src": "assets/liubei-gold-biography.webp", "width": 1536, "height": 1024}, "attack_cg": {"src": "assets/liubei-gold-attack_cg.webp", "width": 1536, "height": 1024}, "avatar": {"src": "assets/liubei-gold-avatar.webp", "width": 1254, "height": 1254}}}, {"hero": "liubei", "id": "heritage5", "tier": 5, "name": "传承刘备", "assets": {"card": {"src": "assets/liubei-heritage5-card.webp", "width": 1190, "height": 1786, "status": "candidate_pending_review"}, "avatar": {"src": "assets/liubei-heritage5-avatar.webp", "width": 1254, "height": 1254, "status": "candidate_pending_review", "qa_note": ""}, "attack_cg": {"src": "assets/liubei-heritage5-attack_cg.webp", "width": 1024, "height": 1536, "status": "candidate_pending_review", "qa_note": ""}, "biography": {"src": "assets/liubei-heritage5-biography.webp", "width": 1672, "height": 941, "status": "candidate_pending_review", "qa_note": ""}}, "story": "江水上涨时，队伍已经走远，刘备却勒住了白马。渡口还有老者未能登船，他把双剑收回鞘中，踏进水里伸出了手。传承不是冠冕上的金纹，而是危急时仍不肯放开的那个人。这一渡，也将少时许下的同行之诺交给了后来者。", "move": "同舟双斩：腾身交错双剑，以翠金剑弧截断敌势，形成护送友军的通路。", "storyTitle": "渡江不弃"}, {"hero": "liubei", "id": "divine5", "tier": 5, "name": "神刘备", "assets": {"card": {"src": "assets/liubei-divine5-card.webp", "width": 1190, "height": 1786, "status": "candidate_pending_review"}, "avatar": {"src": "assets/liubei-divine5-avatar.webp", "width": 1254, "height": 1254, "status": "candidate_pending_review", "qa_note": ""}, "attack_cg": {"src": "assets/liubei-divine5-attack_cg.webp", "width": 1024, "height": 1536, "status": "candidate_pending_review", "qa_note": ""}, "biography": {"src": "assets/liubei-divine5-biography.webp", "width": 1672, "height": 941, "status": "candidate_pending_review", "qa_note": ""}}, "storyTitle": "愿火初明", "story": "神庭许他登临高座，他却听见云下荒村的钟声。刘备收起浮剑，将第一缕神光送入村民捧着的残灯。灯火由一人传向众人，神格也由此有了归处：不是被仰望的冠冕，而是黑夜里仍能找到彼此的微光。", "move": "慈光回环：双剑绕身回旋后向前疾射，金白光环同时展开援护。"}, {"hero": "liubei", "id": "demon5", "tier": 5, "name": "魔刘备", "assets": {"card": {"src": "assets/liubei-demon5-card.webp", "width": 1190, "height": 1786, "status": "candidate_pending_review"}, "avatar": {"src": "assets/liubei-demon5-avatar.webp", "width": 1254, "height": 1254, "status": "candidate_pending_review", "qa_note": ""}, "attack_cg": {"src": "assets/liubei-demon5-attack_cg.webp", "width": 1199, "height": 1312, "status": "candidate_pending_review", "qa_note": ""}, "biography": {"src": "assets/liubei-demon5-biography.webp", "width": 1672, "height": 941, "status": "candidate_pending_review", "qa_note": ""}}, "storyTitle": "孤城守誓", "story": "城门已破，幸存者却仍在等一声归队。刘备踏过灰烬，以自身承接城中失控的怨息。裂纹爬上面颊，旧袍被阴风撕碎，他仍把双剑插在门前，留出通往黎明的窄路。魔意改变了形貌，却没能夺走那句不弃同袍的誓言。", "move": "冥誓错斩：压低身形，以赤焰与紫冥双剑反向突进，切开困住同伴的阴影。"}, {"hero": "liubei", "id": "mecha5", "tier": 5, "name": "机甲刘备", "assets": {"card": {"src": "assets/liubei-mecha5-card.webp", "width": 1190, "height": 1786, "status": "candidate_pending_review"}, "avatar": {"src": "assets/liubei-mecha5-avatar.webp", "width": 1254, "height": 1254, "status": "candidate_pending_review", "qa_note": ""}, "attack_cg": {"src": "assets/liubei-mecha5-attack_cg.webp", "width": 1024, "height": 1536, "status": "candidate_pending_review", "qa_note": ""}, "biography": {"src": "assets/liubei-mecha5-biography.webp", "width": 1672, "height": 941, "status": "candidate_pending_review", "qa_note": ""}}, "storyTitle": "百工铸仁", "story": "洪水冲毁旧桥后，工坊争论该先铸利刃还是修好渡具。刘备与工匠把最后一枚玉核装进巨型机关的胸口，先让它抬起断裂的桥梁。后来它才有了双剑。机甲的第一道命令不是歼敌，而是让被困的人平安回家。", "move": "双驱破阵：玉核增压，机关双臂交叉斩落，双腿喷流完成突进援护。"}, {"hero": "liubei", "id": "heritage6", "tier": 6, "name": "传承刘备", "assets": {"card": {"src": "assets/liubei-heritage6-card.webp", "width": 1024, "height": 1536, "status": "candidate_pending_review"}, "biography": {"src": "assets/liubei-heritage6-biography.webp", "width": 1536, "height": 1024, "status": "candidate_pending_review", "qa_note": ""}, "avatar": {"src": "assets/liubei-heritage6-avatar.webp", "width": 1254, "height": 1254, "status": "candidate_pending_review", "qa_note": ""}, "attack_cg": {"src": "assets/liubei-heritage6-attack_cg.webp", "width": 1024, "height": 1536, "status": "candidate_pending_review", "qa_note": ""}}, "storyTitle": "山河化龙", "story": "当最后一道堤墙崩裂，刘备不再请求山河庇护。他将传承之印融入自身，双足化为苍翠龙躯，沿江盘起新的屏障。百姓踏着金鳞走向高处，仍认得龙首之上那张熟悉的面容。仁德从人的一诺，变成了托举万民的山河之身。", "move": "苍龙济世：龙躯盘旋俯冲，双剑交织为金绿回环，以巨尾回卷护住后方。"}, {"hero": "liubei", "id": "divine6", "tier": 6, "name": "神刘备", "assets": {"card": {"src": "assets/liubei-divine6-card.webp", "width": 1024, "height": 1536, "status": "candidate_pending_review"}, "avatar": {"src": "assets/liubei-divine6-avatar.webp", "width": 1254, "height": 1254, "status": "candidate_pending_review", "qa_note": ""}, "attack_cg": {"src": "assets/liubei-divine6-attack_cg.webp", "width": 1024, "height": 1536, "status": "candidate_pending_review", "qa_note": ""}, "biography": {"src": "assets/liubei-divine6-biography.webp", "width": 1672, "height": 941, "status": "candidate_pending_review", "qa_note": ""}}, "storyTitle": "万愿莲生", "story": "村落里传来的灯火终于汇成一片星海。刘备将自己的神躯化作承接众愿的白玉莲华，多重光轮不是王权的装饰，而是每一份被回应的祈愿。当天界大门关闭，他仍让莲根伸向人间，接住那些尚未被看见的微弱光点。", "move": "万愿轮转：莲华圣躯展开多臂与光轮，双剑化作贯穿前线的慈光锋刃。"}, {"hero": "liubei", "id": "demon6", "tier": 6, "name": "魔刘备", "assets": {"card": {"src": "assets/liubei-demon6-card.webp", "width": 1024, "height": 1536, "status": "candidate_pending_review"}, "avatar": {"src": "assets/liubei-demon6-avatar.webp", "width": 1254, "height": 1254, "status": "candidate_pending_review", "qa_note": ""}, "attack_cg": {"src": "assets/liubei-demon6-attack_cg.webp", "width": 1024, "height": 1536, "status": "candidate_pending_review", "qa_note": ""}, "biography": {"src": "assets/liubei-demon6-biography.webp", "width": 1672, "height": 941, "status": "candidate_pending_review", "qa_note": ""}}, "storyTitle": "冥翼渡魂", "story": "阴界裂隙吞没了归途，刘备循着同袍的呼声进入其中。为撑住正在闭合的通道，他让魔化彻底贯穿身躯，黑翼、龙尾与紫色魂核一同诞生。离去的人只记得，门后那位可怖的守卫，仍以温和的声音请他们先行。", "move": "冥龙断界：振翼折返，龙尾卷起紫焰，双剑斩出交叉裂隙后封住追击。"}, {"hero": "liubei", "id": "mecha6", "tier": 6, "name": "机甲刘备", "assets": {"card": {"src": "assets/liubei-mecha6-card.webp", "width": 1024, "height": 1536, "status": "candidate_pending_review"}, "avatar": {"src": "assets/liubei-mecha6-avatar.webp", "width": 1254, "height": 1254, "status": "candidate_pending_review", "qa_note": ""}, "attack_cg": {"src": "assets/liubei-mecha6-attack_cg.webp", "width": 1024, "height": 1536, "status": "candidate_pending_review", "qa_note": ""}, "biography": {"src": "assets/liubei-mecha6-biography.webp", "width": 1672, "height": 941, "status": "candidate_pending_review", "qa_note": ""}}, "storyTitle": "万家之城", "story": "当一台机关已不足以庇护流离者，刘备把玉核与整座浮城相连。四肢化作堡垒与剑翼，长尾成为稳定云海的龙脊，家园从废墟中缓缓升起。驾驶舱里仍只有那个守诺的人，而他的身躯已成为万家灯火共同栖息的城。", "move": "浮城龙巡：龙尾引擎转向，双剑翼聚束突切，城体护盾同步展开。"}];